// ─── PERSISTANCE LOCALE (préférences UI) ────────────────────────────────────

function useLocalStorage(key, initialValue) {
  const [value, setValue] = useState(() => {
    try {
      const stored = localStorage.getItem(key);
      return stored !== null ? JSON.parse(stored) : initialValue;
    } catch {
      return initialValue;
    }
  });

  const setAndStore = useCallback((newVal) => {
    setValue(prev => {
      const next = typeof newVal === "function" ? newVal(prev) : newVal;
      try { localStorage.setItem(key, JSON.stringify(next)); } catch {}
      return next;
    });
  }, [key]);

  return [value, setAndStore];
}

// ─── PERSISTANCE FIRESTORE (données partagées en temps réel) ─────────────────
//
// IMPORTANT : les articles contiennent des images base64 (~4 MB) qui dépassent
// la limite Firestore de 1 MB. On utilise des transforms pour les exclure du
// document Firestore et les restaurer localement depuis ARTICLE_IMAGES.

function useFirestoreState(fsKey, initialValue, { toFirestore, fromFirestore } = {}) {
  const [value, setValue] = useState(initialValue);
  // Ref toujours synchronisé avec la dernière valeur locale (évite les closures figées)
  const latestValue = useRef(initialValue);

  useEffect(() => { latestValue.current = value; });

  useEffect(() => {
    const docRef = doc(db, "boutique_data", fsKey);
    // includeMetadataChanges: true → on reçoit les changements de métadonnées,
    // ce qui permet de lire snap.metadata.hasPendingWrites.
    //
    // hasPendingWrites = true  → snapshot issu de NOTRE propre écriture locale
    //                            (echo Firestore de notre setDoc, déjà appliqué
    //                            en optimiste) → on IGNORE pour éviter le double apply.
    //
    // hasPendingWrites = false → snapshot venant du serveur : soit confirmation
    //                            de notre propre écriture, soit mise à jour d'un
    //                            AUTRE poste → on APPLIQUE → temps réel garanti.
    const unsub = onSnapshot(
      docRef,
      { includeMetadataChanges: true },
      (snap) => {
        if (_modeEcoleRef.current) return; // Mode École : on n'écrase JAMAIS la simulation avec des données Firestore
        if (snap.metadata.hasPendingWrites) return; // echo local → ignoré
        if (snap.exists() && snap.data().data !== undefined) {
          const raw = snap.data().data;
          const data = fromFirestore ? fromFirestore(raw) : raw;
          latestValue.current = data;
          setValue(data);
        }
      },
      (err) => console.error(`[Firestore] onSnapshot ${fsKey}:`, err)
    );
    return unsub;
  }, [fsKey]);

  const setAndStore = useCallback((newVal) => {
    const next = typeof newVal === "function" ? newVal(latestValue.current) : newVal;
    latestValue.current = next;
    setValue(next); // mise à jour optimiste immédiate (visible sans attendre Firestore)
    if (_modeEcoleRef.current) return; // Mode École : simulation locale uniquement, pas d'écriture Firestore
    const dataToSave = toFirestore ? toFirestore(next) : next;
    setDoc(doc(db, "boutique_data", fsKey), { data: dataToSave })
      .catch(err => console.error(`[Firestore] Erreur écriture ${fsKey}:`, err));
  }, [fsKey, toFirestore, fromFirestore]);

  return [value, setAndStore];
}

// Transforms pour les articles : on ne stocke PAS les images base64 dans Firestore
// (elles font ~4 MB et dépassent la limite de 1 MB par document)
const articlesFirestoreTransforms = {
  toFirestore: (arts) => arts.map(({ image, ...rest }) => rest),
  fromFirestore: (arts) => arts.map(a => ({ ...a, image: a.photoURL || ARTICLE_IMAGES[a.id] || "" })),
};

// ─── UTILITAIRES ────────────────────────────────────────────────────────────

const r2 = (n) => Math.round(n * 100) / 100;
const fmt = (n) => r2(n).toFixed(2) + " €";
const now = () => new Date().toISOString();
const fmtDate = (iso) => {
  const d = new Date(iso);
  return d.toLocaleDateString("fr-FR") + " " + d.toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" });
};

// ─── COMPOSANTS UTILITAIRES ─────────────────────────────────────────────────

const Badge = ({ children, color }) => {
  const dark = useDark();
  const d = dk(dark);
  return <span className={`px-2 py-0.5 rounded-full text-xs font-medium border ${d.badge[color] || d.badge.gray}`}>{children}</span>;
};

const Alert = ({ type, msg, onClose }) => {
  const dark = useDark();
  const d = dk(dark);
  if (!msg) return null;
  const styles = { success: d.alertSuccess, error: d.alertError, warning: d.alertWarning, info: d.alertInfo };
  return (
    <div className={`flex items-center gap-2 p-3 rounded-lg border text-sm mb-3 ${styles[type]}`}>
      {type === "success" && <CheckCircle size={16} />}
      {type === "error" && <XCircle size={16} />}
      {type === "warning" && <AlertTriangle size={16} />}
      <span className="flex-1">{msg}</span>
      {onClose && <button onClick={onClose}><X size={14} /></button>}
    </div>
  );
};

const Modal = ({ title, onClose, children }) => {
  const dark = useDark();
  const d = dk(dark);
  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className={`${d.modal} border rounded-2xl shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto`}>
        <div className={`flex items-center justify-between p-5 border-b ${d.modalHead}`}>
          <h3 className={`font-bold text-lg ${d.text}`}>{title}</h3>
          <button onClick={onClose} className={`p-1.5 rounded-lg transition-colors ${d.btnGhost}`}>
            <X size={18} />
          </button>
        </div>
        <div className="p-5">{children}</div>
      </div>
    </div>
  );
};

