const Btn = ({ children, variant = "primary", size = "md", shop, ...props }) => {
  const dark = useDark();
  const d = dk(dark);
  const base = "inline-flex items-center gap-1.5 font-medium rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed";
  const sizes = { sm: "px-3 py-1.5 text-xs", md: "px-4 py-2 text-sm", lg: "px-5 py-2.5 text-base" };
  const isLocale = shop === "locale";
  const variants = {
    primary: isLocale ? "bg-teal-600 hover:bg-teal-700 text-white shadow-sm" : "text-white shadow-sm",
    secondary: d.btnSecondary,
    danger: "bg-red-600 hover:bg-red-700 text-white",
    ghost: d.btnGhost,
    outline: isLocale ? "border border-teal-600 text-teal-600 hover:bg-teal-50" : "border text-white hover:bg-orange-50",
  };
  const style = (variant === "primary" && !isLocale) ? {background: "#F07800"} : {};
  return <button className={`${base} ${sizes[size]} ${variants[variant]}`} style={style} {...props}>{children}</button>;
};

